import { IconChevronRight } from "@airbus/icons";
import { svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const Breadcrumb: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const colors = {
    separator: color.text.neutral.moderate[mode],
    current: color.text.neutral.strong[mode],
  };

  return {
    root: {
      padding: 0,
      margin: 0,
      display: "flex",
      flexWrap: "wrap",
    },
    item: {
      listStyle: "none",
      position: "relative",
      display: "inline-flex",
      alignItems: "center",
      fontSize: font.size.small,
      lineHeight: font.lineheight.medium,
      "& a": {
        fontSize: font.size.small,
        color: color.text.link.neutral.default[mode],
        textDecoration: "none",
      },
      "&:after": {
        content: "''",
        width: size.spacing[16],
        height: size.spacing[16],
        backgroundImage: svgUri(
          svgColor(IconChevronRight.data, colors.separator)
        ),
        backgroundRepeat: "no-repeat",
        backgroundSize: "100%",
        // marginBottom: 2,
      },
      "&:last-child:after": {
        display: "none",
      },
    },
    item_current: {
      margin: `0 ${size.spacing[8]}`,
      color: colors.current,
    },
    _medium: {
      "& $item": {
        fontSize: font.size.medium,
        "& a": {
          fontSize: font.size.medium,
        },
        "&:after": {
          width: size.spacing[24],
          height: size.spacing[24],
        },
      },
    },
  };
};
